// Base class (Parent)
class Animal {
  public virtual void animalSound() {
    Console.WriteLine("The animal makes a sound");
  }
}

// Derived class (Child)
class Pig : Animal {
  public override void animalSound() {
    Console.WriteLine("The pig says: wee wee");
  }
}

